 if(record.category==='wechat-qr'){if(url){$('#wechat-qr-image').src=url;$('#wechat-qr-image').hidden=false;$('#wechat-qr-placeholder').hidden=true;}return}
 if(record.category==='optical-photo'){if(url)$('#optical-hidden-image').src=url;return}
