function prepareEditableText(){for(const [scope,selector] of Object.entries(textScopes))$$(selector).forEach((element,ei)=>{const walker=document.createTreeWalker(element,NodeFilter.SHOW_TEXT);let node,nodes=[];while(node=walker.nextNode())if(node.textContent.trim()&&!node.parentElement.closest('[data-text-key]'))nodes.push(node);nodes.forEach((text,ti)=>{const span=document.createElement('span');span.dataset.textKey=`${scope}.${ei}.${ti}`;span.textContent=text.textContent;text.replaceWith(span)})});}
