// Binary backup: metadata stays small; original media Blobs are never base64 encoded.
const backupCategories=new Set(['notes','visual','photos','videos','cases','text','cover','record-label','portrait','optical-photo','wechat-qr','skills','case-pages','asset-import','copywriting','copy-images','video-covers']);
function createBinaryBackup(records){
 const parts=[],manifest=[];let offset=0;
 for(const record of records){const r={...record};delete r.url;delete r.blob;
  if(record.blob instanceof Blob){r.binary={offset,size:record.blob.size,type:record.blob.type};parts.push(record.blob);offset+=record.blob.size;}
  manifest.push(r);
 }
 const metadata=new Blob([JSON.stringify({format:'out-of-frame-binary',version:2,records:manifest})]);
 const prefix=new Uint8Array(16);prefix.set(new TextEncoder().encode('OFBACK02'));new DataView(prefix.buffer).setUint32(8,metadata.size,true);
 return new Blob([prefix,metadata,...parts],{type:'application/octet-stream'});
}
async function readPortfolioBackup(file){
 const prefix=new Uint8Array(await file.slice(0,16).arrayBuffer());
 if(new TextDecoder().decode(prefix.slice(0,8))==='OFBACK02'){
  const length=new DataView(prefix.buffer).getUint32(8,true);if(length>32*1024*1024||16+length>file.size)throw Error('备份目录损坏');
  const metadata=JSON.parse(await file.slice(16,16+length).text());
  if(metadata.format!=='out-of-frame-binary'||metadata.version!==2||!Array.isArray(metadata.records))throw Error('备份格式无效');
  return metadata.records.map(record=>{if(!record||typeof record.id!=='string'||!backupCategories.has(record.category))throw Error('备份内容无效');const r={...record};delete r.url;
   if(r.binary){const {offset,size,type}=r.binary;if(!Number.isSafeInteger(offset)||!Number.isSafeInteger(size)||offset<0||size<0||16+length+offset+size>file.size)throw Error('备份媒体不完整');r.blob=file.slice(16+length+offset,16+length+offset+size,type||'application/octet-stream');delete r.binary;}
   return r;
  });
 }
 const backup=JSON.parse(await file.text());
 if(backup.format!=='out-of-frame-content'||backup.version!==1||!Array.isArray(backup.records))throw Error('不是支持的内容备份');
 const restored=[];
 for(const record of backup.records){if(!record||typeof record.id!=='string'||!backupCategories.has(record.category))throw Error('备份格式无效');const r={...record};delete r.url;
  if(r.media){const match=/^data:((?:image|video)\/[\w.+-]+);base64,([A-Za-z0-9+/=\r\n]+)$/.exec(r.media);if(!match)throw Error('媒体格式无效');const raw=atob(match[2]);r.blob=new Blob([Uint8Array.from(raw,c=>c.charCodeAt(0))],{type:match[1]});delete r.media;}restored.push(r);
 }
 return restored;
}
