 const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='留白之外-完整内容备份-'+new Date().toISOString().slice(0,10)+'.ofbackup';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),600000);
 showToast('已发起完整备份下载（'+Math.ceil(blob.size/1024/1024)+'MB）。请等待浏览器下载完成。');
