function moveLens(e){if(lensLocked)return;const rect=specimen.getBoundingClientRect();specimen.style.setProperty('--lens-x',Math.max(8,Math.min(92,(e.clientX-rect.left)/rect.width*100))+'%');specimen.style.setProperty('--lens-y',Math.max(8,Math.min(92,(e.clientY-rect.top)/rect.height*100))+'%')}
