// Reversible, viewport-triggered focus. No scroll locking or wheel interception.
(()=>{
 const preference=matchMedia('(prefers-reduced-motion:reduce)');let focusObserver,boundaryObserver;
 const elements=$$('.about-layout,.section-title,.rail,#notes-grid,#visual-grid,#photo-grid,#video-grid,#case-list,.video-heading,.contact-row,.optical-caption,.optical-specimen');
 const chapters=$$('main>.section,main>.optical-break');
 function stop(){focusObserver?.disconnect();boundaryObserver?.disconnect();document.documentElement.classList.remove('scroll-cinema');elements.forEach(el=>el.classList.remove('soft-reveal','in-focus'));$$('.section-refraction').forEach(el=>el.remove());chapters.forEach(el=>el.classList.remove('boundary-visible'))}
 function start(){stop();if(preference.matches||!('IntersectionObserver' in window))return;
  document.documentElement.classList.add('scroll-cinema');
  focusObserver=new IntersectionObserver(entries=>{entries.forEach(({target,isIntersecting,boundingClientRect:r})=>{if(isIntersecting){target.classList.add('in-focus')}else{target.style.setProperty('--entry-distance',r.bottom<0?'-16px':'22px');target.classList.remove('in-focus')}})},{rootMargin:'0px 0px -28px 0px',threshold:0});
  elements.forEach(el=>{const r=el.getBoundingClientRect();el.classList.add('soft-reveal');if(r.top<innerHeight&&r.bottom>0)el.classList.add('in-focus');focusObserver.observe(el)});
  boundaryObserver=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>target.parentElement.classList.toggle('boundary-visible',isIntersecting)),{rootMargin:'0px',threshold:0});
  chapters.forEach(el=>{el.classList.add('scroll-composition');const glow=document.createElement('span');glow.className='section-refraction';glow.setAttribute('aria-hidden','true');const img=document.createElement('img');img.src=asset('glow.jpg');img.alt='';glow.append(img);el.prepend(glow);boundaryObserver.observe(glow)});
 }
 start();preference.addEventListener('change',start);
})();

// Single scheduled frame per scroll; only on-screen chapter seams are measured.
(()=>{
 const motion=matchMedia('(prefers-reduced-motion:reduce)');let scanObserver,depthObserver,mutations=[],frame=0;const visible=new Set(),scanHosts=new Set();
 const grids=$$('#notes-grid,#visual-grid,#photo-grid,#video-grid');
 function scanRegister(){if(!scanObserver)return;$$('.visual-image,.photo-img').forEach((el,i)=>{if(scanHosts.has(el))return;scanHosts.add(el);if(el.classList.contains('photo-img')){el.classList.add('photo-exposure');scanObserver.observe(el);return}el.classList.add('scan-host');el.style.setProperty('--scan-delay',`${i%3*65}ms`);const sheet=document.createElement('span');sheet.className='scan-sheet';sheet.setAttribute('aria-hidden','true');el.append(sheet);scanObserver.observe(el)});for(const el of scanHosts)if(!el.isConnected){scanObserver.unobserve(el);scanHosts.delete(el)}}
 function draw(){frame=0;if(document.body.matches('.editing,.no-scroll')||motion.matches)return;const h=innerHeight;for(const el of visible){const rect=el.getBoundingClientRect(),p=Math.max(-1,Math.min(1,(rect.top+Math.min(rect.height,h)/2-h/2)/h));if(el.classList.contains('section-refraction')){el.style.setProperty('--light-x',`${p*24}px`);el.style.setProperty('--light-y',`${p*14}px`);el.style.setProperty('--light-angle',`${p*2}deg`)}else el.style.setProperty('--title-drift',`${p*7}px`)}}
 function schedule(){if(!frame)frame=requestAnimationFrame(draw)}
 function teardown(){scanObserver?.disconnect();depthObserver?.disconnect();mutations.forEach(o=>o.disconnect());mutations=[];visible.clear();cancelAnimationFrame(frame);frame=0;removeEventListener('scroll',schedule);removeEventListener('resize',schedule);scanHosts.forEach(el=>{el.classList.remove('scan-host','scan-arrived','photo-exposure','photo-developed');el.querySelector('.scan-sheet')?.remove()});scanHosts.clear();scanObserver=null;$$('.section-title').forEach(el=>el.style.removeProperty('--title-drift'))}
 function setup(){teardown();if(motion.matches||!('IntersectionObserver' in window))return;
 scanObserver=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>target.classList.toggle(target.classList.contains('photo-img')?'photo-developed':'scan-arrived',isIntersecting)),{threshold:.12});scanRegister();
 grids.forEach(grid=>{const observer=new MutationObserver(scanRegister);observer.observe(grid,{childList:true});mutations.push(observer)});
 depthObserver=new IntersectionObserver(entries=>{entries.forEach(({target,isIntersecting})=>isIntersecting?visible.add(target):visible.delete(target));schedule()},{rootMargin:'100px'});$$('.section-refraction,.section-title').forEach(el=>depthObserver.observe(el));addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});schedule();
 }
 setup();motion.addEventListener('change',setup);
})();

// Project pages are separate records. They never overwrite case covers or earlier sections.
function projectPages(caseId){return data['case-pages'].filter(p=>p.caseId===caseId).sort((a,b)=>a.slot-b.slot)}
function casePagesMarkup(caseId){const pages=projectPages(caseId),size=Math.max(3,...pages.map(p=>p.slot+1));return `<div class="case-pages ${data.cases.find(c=>c.id===caseId)?.originalProject?'original-project-pages':''}" data-pages-owner="${esc(caseId)}"><div class="case-pages-heading"><h4>项目内容 / PPT 页面</h4><span>${pages.length} PAGES</span></div><div class="case-page-grid">${Array.from({length:size},(_,slot)=>{const page=pages.find(p=>p.slot===slot);return `<div class="case-page">${page?`<button class="case-page-image" data-page-open="${esc(page.id)}" aria-label="查看项目第 ${slot+1} 页"><img class="${page.originalProject?'original-slide':''} ${page.originalProject==='meows-table'?'meows-portrait':''} ${page.originalProject==='jian-shan-qing'?'jian-portrait':''}" src="${esc(src(page))}" alt="${esc(page.alt||page.title)}" ${page.originalProject?`width="${page.width||1672}" height="${page.height||941}"`:''} loading="lazy" decoding="async"><span>放大查看 ↗</span></button><div class="case-page-caption"><small>${String(slot+1).padStart(2,'0')}</small><button data-page-upload="${esc(caseId)}" data-page-slot="${slot}">替换这页 ↗</button></div>`:`<button class="case-page-empty" data-page-upload="${esc(caseId)}" data-page-slot="${slot}"><b>＋</b><span>添加第 ${slot+1} 页</span><small>PPT 导出图片 / 项目内容</small></button>`}</div>`}).join('')}</div><div class="case-pages-footer"><p>点击图片放大，左右切换浏览本项目。图片完整显示，不裁切。</p><button data-pages-add="${esc(caseId)}">＋ 继续添加内容图片</button>${data.cases.find(c=>c.id===caseId)?.originalProject?`<button data-original-backup="${data.cases.find(c=>c.id===caseId)?.originalProject==='jian-shan-qing'?jianImportId():data.cases.find(c=>c.id===caseId)?.originalProject==='meows-table'?meowsImportId():data.cases.find(c=>c.id===caseId)?.resourceUrl?.includes('pocari-v2')?pocariUpdateId():data.cases.find(c=>c.id===caseId)?.originalProject==='sanfu'?sanfuImportId():originalImageImportId()}">下载导入前内容备份</button>`:''}</div></div>`}
function refreshProjectPages(caseId){const target=$$('[data-pages-owner]').find(el=>el.dataset.pagesOwner===caseId);if(target)target.outerHTML=casePagesMarkup(caseId)}
const projectPageInput=document.createElement('input');projectPageInput.type='file';projectPageInput.accept='image/*';projectPageInput.hidden=true;document.body.append(projectPageInput);let pageUploadTarget=null;
document.addEventListener('click',e=>{const open=e.target.closest('[data-page-open]');if(open){const page=data['case-pages'].find(p=>p.id===open.dataset.pageOpen);if(page){const pages=projectPages(page.caseId);viewImage(pages,pages.findIndex(p=>p.id===page.id))}return}const single=e.target.closest('[data-page-upload]'),add=e.target.closest('[data-pages-add]');if(!single&&!add)return;pageUploadTarget={caseId:single?single.dataset.pageUpload:add.dataset.pagesAdd,slot:single?Number(single.dataset.pageSlot):null};projectPageInput.multiple=!single;projectPageInput.value='';projectPageInput.click()});
projectPageInput.addEventListener('change',async()=>{const target=pageUploadTarget,files=Array.from(projectPageInput.files);if(!target||!files.length)return;projectPageInput.disabled=true;try{await ready;for(const file of files){if(!file.type.startsWith('image/'))throw Error('请先将 PPT 页面导出为 JPG 或 PNG 图片');if(file.size>20*1024*1024)throw Error('单张图片请控制在 20MB 以内')}const used=new Set(projectPages(target.caseId).map(p=>p.slot));const records=files.map((file,i)=>{let slot=target.slot;if(slot===null){slot=0;while(used.has(slot))slot++}else slot+=i;used.add(slot);return {id:'case-page:'+encodeURIComponent(target.caseId)+':'+slot,category:'case-pages',caseId:target.caseId,slot,title:file.name.replace(/\.[^.]+$/,''),description:'',blob:file,created:Date.now()+i}});await putMany(records);records.forEach(activateRecord);refreshProjectPages(target.caseId);showToast(`已保存 ${records.length} 张项目内容图片，原封面及其他内容保持不变`)}catch(err){showToast('未保存：'+err.message)}finally{projectPageInput.disabled=false;projectPageInput.value=''}});

// One-time image-only migration. Existing text and other sections are not rewritten.
function originalImageImportId(){return 'original-marketing-png-20261025-v1'}
function originalImportPlan(){const definitions=[{folder:'pocari',match:/宝矿力|pocari/i,name:'宝矿力水特｜热爱有续航',fallback:0},{folder:'hbn',match:/hbn|好好说清楚/i,name:'HBN｜好好说清楚',fallback:1}];const used=new Set();return definitions.map(d=>{const item=data.cases.find(c=>!used.has(c.id)&&d.match.test(c.title))||data.cases[d.fallback];if(!item||used.has(item.id))throw Error('无法确认前两个案例的位置');used.add(item.id);const cover={...item,category:'cases',resourceUrl:`portfolio-assets/${d.folder}/01.png`,originalProject:d.folder,alt:`${d.name}：营销策划封面，第1页`};delete cover.blob;delete cover.url;delete cover.image;const pages=Array.from({length:5},(_,slot)=>({id:'case-page:'+encodeURIComponent(item.id)+':'+slot,category:'case-pages',caseId:item.id,slot,title:`${d.name} · 第${slot+2}页`,description:'',resourceUrl:`portfolio-assets/${d.folder}/${String(slot+2).padStart(2,'0')}.png`,originalProject:d.folder,alt:`${d.name}：营销策划方案第${slot+2}页，原始图片1672×941`}));return {caseId:item.id,cover,pages}})}
function openImportSnapshots(){return new Promise((resolve,reject)=>{const r=indexedDB.open('out-of-frame-import-snapshots',1);r.onupgradeneeded=()=>r.result.createObjectStore('snapshots',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function saveOriginalSnapshot(records,snapshotId=originalImageImportId()){const backupDb=await openImportSnapshots();try{await new Promise((resolve,reject)=>{const tx=backupDb.transaction('snapshots','readwrite'),store=tx.objectStore('snapshots'),request=store.get(snapshotId);request.onsuccess=()=>{if(!request.result)store.put({id:snapshotId,created:Date.now(),records})};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('备份未完成'))})}finally{backupDb.close()}}
async function importOriginalMarketingImages(saved){if(saved.some(r=>r.id===originalImageImportId()))return;const plan=originalImportPlan();await saveOriginalSnapshot(saved);const ids=new Set(plan.map(p=>p.caseId));const obsolete=saved.filter(r=>r.category==='case-pages'&&ids.has(r.caseId));const additions=[...plan.flatMap(p=>[p.cover,...p.pages]),{id:originalImageImportId(),category:'asset-import',created:Date.now()}];await new Promise((resolve,reject)=>{const tx=db.transaction('works','readwrite'),store=tx.objectStore('works');obsolete.forEach(r=>store.delete(r.id));additions.forEach(r=>store.put(r));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('原图保存失败'))});data['case-pages']=data['case-pages'].filter(p=>!ids.has(p.caseId));obsolete.forEach(r=>savedRecords.delete(r.id));additions.forEach(activateRecord);renderAll();showToast('已备份旧内容，并仅替换前两个案例的原图')}
async function downloadOriginalSnapshot(snapshotId=originalImageImportId()){let backupDb;try{backupDb=await openImportSnapshots();const snapshot=await new Promise((resolve,reject)=>{const r=backupDb.transaction('snapshots').objectStore('snapshots').get(snapshotId);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(!snapshot)throw Error('当前浏览器没有导入前快照');const records=await Promise.all(snapshot.records.map(async record=>{const r={...record};delete r.url;if(r.blob){r.media=await blobDataURL(r.blob);delete r.blob}return r}));const url=URL.createObjectURL(new Blob([JSON.stringify({format:'out-of-frame-content',version:1,records})],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='留白之外-原图导入前内容备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}catch(error){showToast('备份下载失败：'+error.message)}finally{backupDb?.close()}}
document.addEventListener('click',e=>{const cover=e.target.closest('[data-original-cover]');if(cover&&!editing){e.preventDefault();e.stopImmediatePropagation();const item=data.cases.find(c=>c.id===cover.dataset.originalCover);if(item)viewImage(['meows-table','jian-shan-qing'].includes(item.originalProject)?projectPages(item.id):[item,...projectPages(item.id)],0)}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-original-backup]');if(b)downloadOriginalSnapshot(b.dataset.originalBackup||originalImageImportId())});

const sanfuContent={"projectId": "sanfu-switch-your-mode", "sectionNumber": "03", "title": "三福｜今天，切换哪种生活？", "subtitle": "SANFU · Switch Your Mode", "type": "品牌整合营销策划｜个人独立模拟项目", "description": "围绕年轻人的上课、实习与周末场景，以音乐连接穿搭与生活方式，设计线上互动、社媒传播及线下门店体验。", "tags": ["品牌营销", "创意策划", "社媒传播", "线下活动"], "stages": [{"title": "01 用户洞察", "description": "探索年轻人的多场景穿搭需求。"}, {"title": "02 创意策划", "description": "以音乐连接穿搭与生活方式。"}, {"title": "03 营销落地", "description": "结合社媒传播与线下门店互动。"}], "status": "个人模拟策划｜未实际执行", "images": [{"src": "/portfolio/sanfu/01-cover.png", "alt": "项目封面", "order": 1}, {"src": "/portfolio/sanfu/02-insight.png", "alt": "消费者洞察", "order": 2}, {"src": "/portfolio/sanfu/03-idea.png", "alt": "创意方案", "order": 3}, {"src": "/portfolio/sanfu/04-communication.png", "alt": "传播内容", "order": 4}, {"src": "/portfolio/sanfu/05-offline.png", "alt": "线下活动", "order": 5}, {"src": "/portfolio/sanfu/06-plan.png", "alt": "执行节奏", "order": 6}]};
function sanfuImportId(){return 'sanfu-original-import-20261025-v1'}
function sanfuImportPlan(){const item=data.cases.find(c=>c.id==='c3')||data.cases.find(c=>/一个活动的创意提案/.test(c.title));if(!item)throw Error('未找到第三个创意策划案例，未修改任何案例');const c=sanfuContent,images=[...c.images].sort((a,b)=>a.order-b.order);const cover={...item,category:'cases',title:c.title,subtitle:c.subtitle,type:c.type,tag:c.type,tags:c.tags,description:c.description,status:c.status,steps:c.stages.map(s=>({title:s.title,body:s.description})),demo:false,originalProject:'sanfu',resourceUrl:images[0].src.replace(/^\//,''),alt:'三福个人模拟策划：'+images[0].alt};delete cover.blob;delete cover.url;delete cover.image;const pages=images.slice(1).map((im,slot)=>({id:'case-page:'+encodeURIComponent(item.id)+':'+slot,category:'case-pages',caseId:item.id,slot,title:im.alt,description:'',resourceUrl:im.src.replace(/^\//,''),originalProject:'sanfu',alt:'三福个人模拟策划：'+im.alt}));return {caseId:item.id,cover,pages}}
async function importSanfuCase(saved){if(saved.some(r=>r.id===sanfuImportId()))return;const plan=sanfuImportPlan();await saveOriginalSnapshot(saved,sanfuImportId());const obsolete=saved.filter(r=>r.category==='case-pages'&&r.caseId===plan.caseId);const additions=[plan.cover,...plan.pages,{id:sanfuImportId(),category:'asset-import',created:Date.now()}];await new Promise((resolve,reject)=>{const tx=db.transaction('works','readwrite'),store=tx.objectStore('works');obsolete.forEach(r=>store.delete(r.id));additions.forEach(r=>store.put(r));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('三福案例导入失败'))});data['case-pages']=data['case-pages'].filter(p=>p.caseId!==plan.caseId);obsolete.forEach(r=>savedRecords.delete(r.id));additions.forEach(activateRecord);renderAll();showToast('已备份原内容，仅更新第三个三福模拟策划案例')}

function pocariUpdateId(){return 'pocari-revised-png-20261025-v2'}
function pocariUpdatePlan(){const item=data.cases.find(c=>c.id==='c1')||data.cases.find(c=>/宝矿力|pocari/i.test(c.title));if(!item)throw Error('未找到宝矿力案例');const cover={...item,category:'cases',resourceUrl:'portfolio/pocari-v2/01.png',originalProject:'pocari',alt:'宝矿力水特：热爱有续航，新版封面'};delete cover.blob;delete cover.url;delete cover.image;const pages=Array.from({length:5},(_,slot)=>({id:'case-page:'+encodeURIComponent(item.id)+':'+slot,category:'case-pages',caseId:item.id,slot,title:'宝矿力水特 · 第'+(slot+2)+'页',description:'',resourceUrl:'portfolio/pocari-v2/0'+(slot+2)+'.png',originalProject:'pocari',alt:'宝矿力水特新版策划：'+['项目背景与用户洞察','核心创意：不是冠军也有高光','整合传播四阶段','核心玩法四宫格','执行评估与预期成果'][slot]}));return {caseId:item.id,cover,pages}}
async function updatePocariImages(saved){if(saved.some(r=>r.id===pocariUpdateId()))return;const plan=pocariUpdatePlan();await saveOriginalSnapshot(saved,pocariUpdateId());const obsolete=saved.filter(r=>r.category==='case-pages'&&r.caseId===plan.caseId);const additions=[plan.cover,...plan.pages,{id:pocariUpdateId(),category:'asset-import',created:Date.now()}];await new Promise((resolve,reject)=>{const tx=db.transaction('works','readwrite'),store=tx.objectStore('works');obsolete.forEach(r=>store.delete(r.id));additions.forEach(r=>store.put(r));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('新版图片保存失败'))});data['case-pages']=data['case-pages'].filter(p=>p.caseId!==plan.caseId);obsolete.forEach(r=>savedRecords.delete(r.id));data.cases=data.cases.map(c=>c.id===plan.caseId?plan.cover:c);additions.forEach(activateRecord);renderAll();showToast('宝矿力新版原图已替换，原文案保持不变')}

// Independent copywriting records keep existing text keys and media untouched.
function copyRender(){let section=$('#copywriting');if(!section){section=document.createElement('section');section.id='copywriting';section.className='copywriting';section.innerHTML=`<div class="copy-rail"><span>WORDS / SELECTED WRITING</span><span>文字，先于画面抵达。</span></div><div class="copy-heading"><h2><span data-text-key="copy.heading.en">Words that <i>stay.</i></span><small data-text-key="copy.heading.zh">文案展示</small></h2><img src="${esc(asset('zero.jpg'))}" alt="" aria-hidden="true"></div><div id="copy-list"></div><div class="copy-controls"><button data-copy-new>＋ 添加文案项目</button><button data-copy-recover hidden>恢复最近移除的内容</button></div><input id="copy-file" type="file" accept="image/*" multiple hidden>`;$('.contact').before(section);const d=document.createElement('dialog');d.id='copy-editor';d.innerHTML='<button type="button" class="close" aria-label="关闭文案编辑">×</button><form id="copy-form"><p class="mono">COPY / EDIT</p><h2>编辑文案</h2><label>标题<input name="title" maxlength="160" required></label><label>项目标识 / 类型<input name="subtitle" maxlength="160"></label><label>正文（支持换行与空行）<textarea name="description" rows="14"></textarea></label><p id="copy-status" role="status"></p><button class="submit" type="submit">保存文案</button></form>';document.body.append(d);d.querySelector('.close').onclick=()=>d.close();d.addEventListener('close',()=>document.body.classList.remove('no-scroll'));$('#copy-form').addEventListener('submit',saveCopy);$('#copy-file').addEventListener('change',addCopyImages)}$('#copy-list').innerHTML=data.copywriting.filter(n=>!n.removed).map((n,i)=>{const images=data['copy-images'].filter(p=>p.ownerId===n.id&&!p.removed);return `<article class="copy-project"><div class="copy-project-top"><span>${String(i+1).padStart(2,'0')} / ${esc(n.subtitle)}</span><div><button data-copy-edit="${esc(n.id)}">编辑文案 ↗</button><button data-copy-remove="${esc(n.id)}">移除项目</button></div></div><div class="copy-layout"><aside class="copy-media">${images.length?images.map(p=>`<figure><button class="copy-image" data-copy-view="${esc(p.id)}" aria-label="放大文案配图：${esc(p.title)}"><img src="${esc(src(p))}" alt="${esc(p.title)}" loading="lazy"></button><figcaption><button data-copy-replace="${esc(p.id)}">替换</button><button data-copy-image-remove="${esc(p.id)}">移除</button></figcaption></figure>`).join(''):'<div class="copy-empty"><span>IMAGE / OPTIONAL</span><p>留一张画面，<br>让文字展开。</p></div>'}<button class="copy-add-image" data-copy-upload="${esc(n.id)}">＋ 添加配图（可多选）</button></aside><div class="copy-text"><h3>${esc(n.title)}</h3><div class="copy-body">${esc(n.description)}</div></div></div></article>`}).join('');$('#copywriting [data-copy-recover]').hidden=![...data.copywriting,...data['copy-images']].some(n=>n.removed);applyTextEdits()}
function editCopy(id){const n=data.copywriting.find(n=>n.id===id)||{title:'',subtitle:'',description:''};const f=$('#copy-form');f.dataset.id=id||'';for(const k of ['title','subtitle','description'])f.elements[k].value=n[k]||'';$('#copy-status').textContent='';showDialog($('#copy-editor'))}
async function saveCopy(e){e.preventDefault();const f=e.currentTarget,button=f.querySelector('.submit');button.disabled=true;try{await ready;const old=data.copywriting.find(n=>n.id===f.dataset.id);const r={...old,id:old?.id||crypto.randomUUID(),category:'copywriting',title:f.elements.title.value.trim(),subtitle:f.elements.subtitle.value.trim(),description:f.elements.description.value.replace(/\r\n/g,'\n'),created:old?.created||Date.now()};if(!r.title)throw Error('请填写标题');await putMany([r]);activateRecord(r);copyRender();$('#copy-editor').close();showToast('文案已保存，换行与段落已保留')}catch(err){$('#copy-status').textContent='未保存：'+err.message}finally{button.disabled=false}}
async function addCopyImages(){const input=$('#copy-file'),files=Array.from(input.files);if(!files.length)return;try{await ready;for(const f of files)if(!f.type.startsWith('image/')||f.size>20*1024*1024)throw Error('请选择单张20MB以内的图片');const old=data['copy-images'].find(n=>n.id===input.dataset.replace);const records=files.map((f,i)=>({id:old?.id||crypto.randomUUID(),category:'copy-images',ownerId:old?.ownerId||input.dataset.owner,title:f.name.replace(/\.[^.]+$/,''),blob:f,created:old?.created||Date.now()+i,removed:false}));await putMany(records);records.forEach(activateRecord);copyRender();showToast('配图已保存，可继续添加或移除')}catch(err){showToast('未保存：'+err.message)}input.value=''}
async function copyVisibility(category,id,removed){try{await ready;const n=data[category].find(n=>n.id===id);if(!n)return;const r={...n,category,removed,removedAt:removed?Date.now():0};delete r.url;await putMany([r]);activateRecord(r);copyRender();showToast(removed?'已移除，可在模块底部恢复':'已恢复')}catch(err){showToast('未保存：'+err.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('#copywriting button');if(!b)return;if(b.hasAttribute('data-copy-new'))editCopy('');if(b.dataset.copyEdit)editCopy(b.dataset.copyEdit);if(b.dataset.copyUpload||b.dataset.copyReplace){const input=$('#copy-file');input.dataset.owner=b.dataset.copyUpload||'';input.dataset.replace=b.dataset.copyReplace||'';input.multiple=!b.dataset.copyReplace;input.value='';input.click()}if(b.dataset.copyView){const p=data['copy-images'].find(n=>n.id===b.dataset.copyView);const list=data['copy-images'].filter(n=>n.ownerId===p.ownerId&&!n.removed);viewImage(list,list.findIndex(n=>n.id===p.id))}if(b.dataset.copyRemove)copyVisibility('copywriting',b.dataset.copyRemove,true);if(b.dataset.copyImageRemove)copyVisibility('copy-images',b.dataset.copyImageRemove,true);if(b.hasAttribute('data-copy-recover')){const n=[...data.copywriting,...data['copy-images']].filter(n=>n.removed).sort((a,b)=>b.removedAt-a.removedAt)[0];if(n)copyVisibility(n.category,n.id,false)}});

