function meowsImportId(){return 'meows-table-import-20261025-v1'}
function meowsImportPlan(){const item=data.cases.find(c=>c.id==='c3')||data.cases.find(c=>c.originalProject==='sanfu');if(!item)throw Error('未找到第三个三福案例，未作修改');const c=meowsContent,images=[...c.images].sort((a,b)=>a.order-b.order);const cover={...item,category:'cases',title:c.title,subtitle:c.englishTitle,tag:c.category,type:c.category,description:c.tagline+'\n\n'+c.description,steps:c.caseStages.map(s=>({title:s.title,body:s.content,english:s.english})),disclaimer:c.disclaimer,sourceUrl:c.source.url,projectType:c.projectType,demo:false,originalProject:'meows-table',width:images[0].width,height:images[0].height,resourceUrl:'portfolio/meows-table/'+images[0].file.split('/').pop(),alt:'喵的饭局：'+images[0].alt};for(const key of ['blob','url','image','status','tags'])delete cover[key];const pages=images.slice(1).map((im,slot)=>({id:'case-page:'+encodeURIComponent(item.id)+':'+slot,category:'case-pages',caseId:item.id,slot,title:'MEOW’S TABLE · '+im.title,description:'概念效果展示，部分为AI辅助生成；图片中的数据、日期和包装不代表真实成果或官方信息。活动未实际执行。',resourceUrl:'portfolio/meows-table/'+im.file.split('/').pop(),originalProject:'meows-table',width:im.width,height:im.height,alt:'喵的饭局：'+im.alt+'（概念展示）'}));return {caseId:item.id,cover,pages}}
async function importMeowsCase(saved){if(saved.some(r=>r.id===meowsImportId()))return;const plan=meowsImportPlan();await saveOriginalSnapshot(saved,meowsImportId());const obsolete=saved.filter(r=>r.category==='case-pages'&&r.caseId===plan.caseId);const additions=[plan.cover,...plan.pages,{id:meowsImportId(),category:'asset-import',created:Date.now()}];await new Promise((resolve,reject)=>{const tx=db.transaction('works','readwrite'),store=tx.objectStore('works');obsolete.forEach(r=>store.delete(r.id));additions.forEach(r=>store.put(r));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('喵的饭局保存失败'))});data['case-pages']=data['case-pages'].filter(p=>p.caseId!==plan.caseId);data.cases=data.cases.map(c=>c.id===plan.caseId?plan.cover:c);obsolete.forEach(r=>savedRecords.delete(r.id));additions.forEach(activateRecord);renderAll();showToast('已备份旧内容，仅将第三个案例更新为喵的饭局')}

function caseSourceLink(item){const sources={c1:['https://www.sina.cn/news/detail/5346714976519447.html','宝矿力水特 · 2026 学院奖秋季征集大赛策略单'],c2:['https://www.shejijingsai.com/2026/03/1519567.html','HBN · 2026 第18届全国大学生广告艺术大赛命题策略单']};const source=sources[item.id];return source?`<p class="case-source-link" style="font-size:12px;line-height:1.8;margin:24px 0;color:inherit"><a href="${source[0]}" target="_blank" rel="noopener noreferrer" style="text-decoration:underline;text-underline-offset:4px">命题来源：${source[1]} ↗</a></p>`:''}

const jianContent={"id": "jian-shan-qing", "project_title": "见山青｜年轻人的下一杯茶", "project_title_en": "JIAN SHAN QING", "eyebrow": "BRAND STRATEGY / PRODUCT LAUNCH CAMPAIGN", "project_type": "茶饮品牌概念策划｜新品上市活动策划", "industry": "茶饮 / 果茶 / 年轻消费", "project_source": "第六届元气森林宇宙大赛（2026）", "source_track": "产品赛道", "official_prompt": "年轻人的下一杯茶", "source_url": "https://www.yuanqisenlin.com/", "source_note": "官方“年轻人的下一杯茶”为产品赛道题目；本案自行延伸了概念品牌与新品上市营销活动，并非官方命题要求开展“山野茶亭”活动。", "project_status": "个人独立模拟策划｜非正式参赛作品｜非元气森林官方合作项目", "tagline": "把山野泡进日常，把元气喝进今天。", "short_intro": "以“年轻人的下一杯茶”为创作起点，提出概念茶饮品牌「见山青」。将中国茶底与山野果香结合，从青年饮茶洞察、产品定位、视觉符号到“山野茶亭”快闪活动，串联一套新品上市传播提案。", "long_intro": "参考2026年第六届元气森林宇宙大赛产品赛道“年轻人的下一杯茶”，尝试回答传统中国茶如何以更轻盈、年轻且有文化记忆的方式进入日常。项目提出概念品牌「见山青」，以山形曲线与圆点作为贯穿视觉，规划四款果香茶饮，并构想校园及城市公共场景的“山野茶亭”快闪、社媒内容种草与试饮转化闭环。本案为独立模拟提案，视觉为概念示意，未实际落地。", "case_stages": [{"title": "01｜从茶饮需求出发", "body": "以“年轻人的下一杯茶”为命题，围绕中国茶风味、果香体验与校园及都市日常场景，提炼可被年轻人感知的品牌切入点。"}, {"title": "02｜把中国茶做年轻", "body": "提出「见山青」品牌概念，设计四款果香茶饮，并用一条山形曲线与一颗圆点贯穿杯身、包装和传播主视觉。"}, {"title": "03｜让茶走进真实场景", "body": "策划「山野茶亭」快闪与社媒传播：内容预热、试饮互动、扫码领券及分享种草形成传播路径；设置参与、试饮和转化指标用于后续评估。"}], "credits": "策划、品牌概念与视觉统筹：个人独立完成；视觉概念图使用生成式 AI 辅助制作。", "hero_image": "assets/00_hero_wide.png", "detail_images": ["assets/01_project_cover.png", "assets/02_project_background.png", "assets/03_brand_concept.png", "assets/04_product_strategy.png", "assets/05_visual_identity.png", "assets/06_brand_application.png", "assets/07_launch_campaign.png", "assets/08_project_summary.png"], "asset_manifest": "image_manifest.json"};
const jianManifest=[{"order": 0, "file": "assets/00_hero_wide.png", "alt": "首页横版封面｜晨光山野中的三杯见山青茶饮", "width": 1672, "height": 941, "sha256": "3dbad496de81c841afa2753b08c40c92aa4f7e88ed845fa88d74b51036d24d44", "role": "portfolio_thumbnail_and_hero"}, {"order": 1, "file": "assets/01_project_cover.png", "alt": "01 竖版项目主视觉｜年轻人的下一杯茶", "width": 1086, "height": 1448, "sha256": "b93c0018a5cac22e7d49ba142f989d2e82d5b438f1834200c391e251ad41cc3e", "role": "portfolio_detail_slide"}, {"order": 2, "file": "assets/02_project_background.png", "alt": "02 项目背景｜青年饮茶需求与概念洞察", "width": 1086, "height": 1448, "sha256": "8ddb7b96859112eba84cd738ec8a62abdff305f80b7ea2ffdac73087f3356bc7", "role": "portfolio_detail_slide"}, {"order": 3, "file": "assets/03_brand_concept.png", "alt": "03 品牌概念｜中国茶与山野果香", "width": 1086, "height": 1448, "sha256": "c420d2d21b3bd065e4ea03015dfc94e314b9f805bf88ed116c1246614de30f86", "role": "portfolio_detail_slide"}, {"order": 4, "file": "assets/04_product_strategy.png", "alt": "04 产品策略｜四款概念茶饮", "width": 1086, "height": 1448, "sha256": "cd564923ab8c78a9c4d40cf7fd20bf168402f6f915519475e803fe680542ce08", "role": "portfolio_detail_slide"}, {"order": 5, "file": "assets/05_visual_identity.png", "alt": "05 视觉系统｜山形曲线与圆点识别", "width": 1086, "height": 1448, "sha256": "0ce9184baa118daf2c75179bf546e0f7188cc4cbd7dce92114ff45b87d7aacc2", "role": "portfolio_detail_slide"}, {"order": 6, "file": "assets/06_brand_application.png", "alt": "06 应用延展｜茶杯、手提袋与传播物料", "width": 1086, "height": 1448, "sha256": "eabefced570b948e260e82879d2d9c3da0f995cb7747ef867f2724358ddc78af", "role": "portfolio_detail_slide"}, {"order": 7, "file": "assets/07_launch_campaign.png", "alt": "07 上市传播｜山野茶亭线下快闪概念", "width": 1086, "height": 1448, "sha256": "c84cb1dc267dbf9f38dd627ded7c27719b6a9161a99311d83c54ccf8f05ab878", "role": "portfolio_detail_slide"}, {"order": 8, "file": "assets/08_project_summary.png", "alt": "08 项目总结｜从新品概念到传播路径", "width": 1086, "height": 1448, "sha256": "b89d8160a606c9ebadca344881e5952533fe953b68776367e564dd62a6843162", "role": "portfolio_detail_slide"}];
function jianImportId(){return 'jian-shan-qing-import-v1'}
function orderPortfolioCases(){if(!data.cases.some(c=>c.id==='jian-shan-qing'))return;const order=['c3','jian-shan-qing','c2','c1'];data.cases.sort((a,b)=>{const rank=x=>order.includes(x.id)?order.indexOf(x.id):4;return rank(a)-rank(b)})}
function jianDetails(n){if(n.originalProject!=='jian-shan-qing')return '';return `<aside class="jian-source"><strong>${esc(n.projectStatus)}</strong><p>${esc(n.longIntro)}</p><p>${esc(n.projectSource)} · ${esc(n.sourceTrack)}<br>${esc(n.sourceNote)}</p><p>${esc(n.credits)}</p><a href="${esc(n.sourceUrl)}" target="_blank" rel="noopener noreferrer">赛事来源：品牌官网 ↗</a></aside>`}
function jianImportPlan(){const c=jianContent,images=[...jianManifest].sort((a,b)=>a.order-b.order),id=c.id;const cover={id,category:'cases',title:c.project_title,subtitle:c.project_title_en,tag:c.project_type,description:c.tagline+'\n\n'+c.short_intro,steps:c.case_stages,eyebrow:c.eyebrow,industry:c.industry,tags:[c.industry],projectSource:c.project_source,sourceTrack:c.source_track,sourceNote:c.source_note,sourceUrl:c.source_url,projectStatus:c.project_status,longIntro:c.long_intro,credits:c.credits,originalProject:id,resourceUrl:'portfolio/jian-shan-qing/00_hero_wide.png',width:1672,height:941,alt:images[0].alt};const pages=images.slice(1).map((im,slot)=>({id:'case-page:'+id+':'+slot,category:'case-pages',caseId:id,slot,title:im.alt,alt:im.alt,description:c.project_status,originalProject:id,resourceUrl:'portfolio/jian-shan-qing/'+im.file.split('/').pop(),width:im.width,height:im.height}));return {cover,pages}}
async function importJianCase(saved){if(saved.some(r=>r.id===jianImportId()))return;if(saved.some(r=>r.id==='jian-shan-qing'))return;const plan=jianImportPlan();await saveOriginalSnapshot(saved,jianImportId());const additions=[plan.cover,...plan.pages,{id:jianImportId(),category:'asset-import',created:Date.now()}];await putMany(additions);additions.forEach(activateRecord);renderAll();showToast('见山青已加入，四个项目已按指定顺序排列；已有内容保留')}

// Visual management writes only the selected item's visibility or chosen category.
function visualTags(){return [...new Set(['海报','品牌视觉','实验设计',...data.visual.map(n=>n.tag).filter(Boolean)])]}
function syncVisualImport(category){let label=$('#import-visual-label');if(!label){label=document.createElement('label');label.id='import-visual-label';label.innerHTML='加入哪个小模块<select id="import-visual-tag"></select>';$('#category').closest('label').after(label)}label.hidden=category!=='visual';const options=visualTags();$('#import-visual-tag').innerHTML=options.map(t=>`<option value="${esc(t)}">${esc(categoryLabel(t)||t)}</option>`).join('');$('#import-visual-tag').value=options.includes(filter)?filter:options[0]}
function visualManageControls(){const end=$('#visual .section-end');let controls=$('#visual-management');if(!controls){controls=document.createElement('div');controls.id='visual-management';controls.style.cssText='display:flex;gap:18px;flex-wrap:wrap;align-items:center';controls.innerHTML='<button type="button" data-visual-manage>管理 / 移除作品</button><button type="button" data-visual-trash hidden></button>';end.append(controls)}const count=data.visual.filter(n=>n.removed).length;const b=controls.querySelector('[data-visual-trash]');b.hidden=!count;b.textContent='恢复已移除作品（'+count+'）'}
async function setVisualRemoved(id,removed){try{await ready;const item=data.visual.find(n=>n.id===id);if(!item)throw Error('未找到作品');const record={...item,category:'visual',removed};delete record.url;await putMany([record]);activateRecord(record);visualRender();if(detail.open)detail.close();if(viewer.open)viewer.close();showToast(removed?'已移除，图片和文字仍保留，可在模块底部恢复':'作品已恢复到原分类')}catch(error){showToast('未保存：'+error.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-visual-manage')){setEditing(true);showToast('点击要管理的视觉作品，可调整分类或移除')}if(b.dataset.visualRemove)setVisualRemoved(b.dataset.visualRemove,true);if(b.dataset.visualRestore)setVisualRemoved(b.dataset.visualRestore,false);if(b.hasAttribute('data-visual-trash')){showContent(`<h2>已移除的视觉作品</h2><p>恢复后回到原来的分类，图片和文案不变。</p><div style="display:grid;gap:20px;margin-top:30px">${data.visual.filter(n=>n.removed).map(n=>`<div style="display:flex;justify-content:space-between;gap:20px;border-top:1px solid #9aa5a5;padding-top:16px"><span>${esc(n.title)} · ${esc(categoryLabel(n.tag))}</span><button data-visual-restore="${esc(n.id)}">恢复 ↗</button></div>`).join('')}</div>`)}});

function videoManageControls(){let b=$('#video-restore');if(!b){b=document.createElement('button');b.id='video-restore';b.type='button';$('#video-grid').nextElementSibling.append(b);const input=document.createElement('input');input.type='file';input.accept='image/*';input.hidden=true;input.id='video-cover-input';document.body.append(input);input.addEventListener('change',saveVideoCover)}const count=data.videos.filter(n=>n.removed).length;b.hidden=!count;b.textContent='恢复已移除视频（'+count+'）'}
async function saveVideoCover(){const input=$('#video-cover-input'),file=input.files[0];if(!file)return;try{await ready;if(!file.type.startsWith('image/')||file.size>20*1024*1024)throw Error('请选择20MB以内的封面图片');const id=input.dataset.owner;const record={id:'video-cover:'+id,category:'video-covers',ownerId:id,title:'视频封面',blob:file};await putMany([record]);activateRecord(record);videoRender();showToast('视频封面已保存，原视频未改动')}catch(error){showToast('未保存：'+error.message)}input.value=''}
async function setVideoRemoved(id,removed){try{await ready;const n=data.videos.find(n=>n.id===id);if(!n)return;const r={...n,category:'videos',removed};delete r.url;await putMany([r]);activateRecord(r);videoRender();if(viewer.open)viewer.close();showToast(removed?'已从页面移除，可在剪辑作品底部恢复':'视频与封面已恢复')}catch(error){showToast('未保存：'+error.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.videoEdit)openItemEdit('videos',data.videos.findIndex(n=>n.id===b.dataset.videoEdit));if(b.dataset.videoCover){const input=$('#video-cover-input');input.dataset.owner=b.dataset.videoCover;input.value='';input.click()}if(b.dataset.videoRemove)setVideoRemoved(b.dataset.videoRemove,true);if(b.dataset.videoRestore)setVideoRemoved(b.dataset.videoRestore,false);if(b.id==='video-restore')showContent(`<h2>已移除的剪辑作品</h2><p>视频、封面与文案仍保留，恢复后回到原位置。</p><div class="video-restore-list">${data.videos.filter(n=>n.removed).map(n=>`<div><span>${esc(n.title)}</span><button data-video-restore="${esc(n.id)}">恢复 ↗</button></div>`).join('')}</div>`)});

// Public presentation: editing remains available in the separate original local file.
document.addEventListener("click",e=>{if(e.target.closest(".owner-tools,.add-open,#edit-toolbar,#cover-change,#label-change,#portrait-change,#optical-photo-change,#skill-add,#sleeve-text-change,#wechat-qr-change,#contact-edit,.case-edit,[data-page-upload],[data-pages-add],[data-original-backup],.copy-controls,[data-copy-edit],[data-copy-upload],[data-copy-replace],[data-copy-remove],[data-copy-image-remove],[data-copy-recover],.video-item-tools,#video-restore,#visual-management,#add-video-now,[data-skill]")){e.preventDefault();e.stopImmediatePropagation();}},true);

// Reliable click + keyboard activation for published video cards.
// Run in capture phase so the legacy page's generic click delegate cannot swallow a video click.
document.addEventListener('click',function(event){
  const card=event.target.closest?.('#video-grid .video-card[data-video]');
  if(!card)return;
  event.preventDefault();
  event.stopImmediatePropagation();
  videoOpen(Number(card.dataset.video));
},true);
